london-penetration-depth-coherence-lengt.js:
(() => {
  'use strict';
  const nsEl = document.getElementById('lon-ns'), xiEl = document.getElementById('lon-xi'), mEl = document.getElementById('lon-mass');
  const lResEl = document.getElementById('lon-res-lam'), kpResEl = document.getElementById('lon-res-kappa');

  const mu0 = 4.0 * Math.PI * 1e-7;
  const e_charge = 1.602176634e-19;
  const m_e = 9.1093837e-31;

  function update() {
    const ns_factor = parseFloat(nsEl.value), xiNm = parseFloat(xiEl.value), massRatio = parseFloat(mEl.value);
    if (isNaN(ns_factor) || isNaN(xiNm) || isNaN(massRatio) || ns_factor <= 0 || xiNm <= 0 || massRatio <= 0) return;

    const ns = ns_factor * 1e28; // Cooper pair super-electron density
    const m_eff = massRatio * m_e;

    // London penetration depth: lambda_L = sqrt( m / (mu0 * ns * e^2) )  [meters]
    const lambda_m = Math.sqrt(m_eff / (mu0 * ns * Math.pow(e_charge, 2)));
    const lambda_nm = lambda_m * 1e9;

    // Ginzburg-Landau parameter kappa = lambda / xi
    const kappa = lambda_nm / xiNm;

    let scType = '';
    let color = '#22543d';

    if (kappa < 0.70710678) {
      scType = 'TYPE I SUPERCONDUCTOR (κ = ' + kappa.toFixed(3) + ' < 1/√2: Complete Meissner Expulsion, Positive Surface Energy)';
      color = '#2563eb';
    } else {
      scType = 'TYPE II SUPERCONDUCTOR (κ = ' + kappa.toFixed(2) + ' > 1/√2: High-Field Abrikosov Vortex Mixed State)';
      color = '#22543d';
    }

    lResEl.textContent = 'λ_L = ' + lambda_nm.toFixed(1) + ' nm Meissner Screening Depth';
    kpResEl.textContent = scType + ' | ξ = ' + xiNm + ' nm (London λ_L = ' + lambda_nm.toFixed(1) + ' nm)';
    kpResEl.style.color = color;
  }

  [nsEl, xiEl, mEl].forEach(el => el.addEventListener('input', update));
  update();
})();

lorem-ipsum-generator.js:
(() => {
  'use strict';
  const countEl = document.getElementById('li-count'), typeEl = document.getElementById('li-type'), outEl = document.getElementById('li-output');
  const btn = document.getElementById('primary-action-btn'), clearBtn = document.getElementById('clear-action-btn'), copyBtn = document.getElementById('copy-li-btn');
  const msgEl = document.getElementById('tool-message');

  const WORDS = ['lorem', 'ipsum', 'dolor', 'sit', 'amet', 'consectetur', 'adipiscing', 'elit', 'sed', 'do', 'eiusmod', 'tempor', 'incididunt', 'ut', 'labore', 'et', 'dolore', 'magna', 'aliqua', 'enim', 'ad', 'minim', 'veniam', 'quis', 'nostrud', 'exercitation', 'ullamco', 'laboris', 'nisi', 'aliquip', 'ex', 'ea', 'commodo', 'consequat', 'duis', 'aute', 'irure', 'in', 'reprehenderit', 'voluptate', 'velit', 'esse', 'cillum', 'fugiat', 'nulla', 'pariatur', 'excepteur', 'sint', 'occaecat', 'cupidatat', 'non', 'proident', 'sunt', 'culpa', 'qui', 'officia', 'deserunt', 'mollit', 'anim', 'id', 'est', 'laborum'];

  function makeSentence() {
    const len = 8 + Math.floor(Math.random() * 8);
    const words = [];
    for (let i = 0; i < len; i++) {
      words.push(WORDS[Math.floor(Math.random() * WORDS.length)]);
    }
    const str = words.join(' ');
    return str.charAt(0).toUpperCase() + str.slice(1) + '.';
  }

  function makeParagraph() {
    const sCount = 4 + Math.floor(Math.random() * 3);
    const sens = [];
    for (let i = 0; i < sCount; i++) sens.push(makeSentence());
    return sens.join(' ');
  }

  function generate() {
    const count = Math.min(50, Math.max(1, parseInt(countEl.value, 10) || 3));
    const type = typeEl.value;

    let res = '';
    if (type === 'words') {
      const w = [];
      for (let i = 0; i < count; i++) w.push(WORDS[Math.floor(Math.random() * WORDS.length)]);
      res = w.join(' ');
    } else if (type === 'sentences') {
      const s = [];
      for (let i = 0; i < count; i++) s.push(makeSentence());
      res = s.join(' ');
    } else {
      const p = [];
      for (let i = 0; i < count; i++) p.push(makeParagraph());
      res = p.join('\n\n');
    }

    outEl.value = res;
    msgEl.textContent = 'Generated ' + count + ' ' + type + '.';
  }

  btn.addEventListener('click', generate);
  typeEl.addEventListener('change', generate);
  countEl.addEventListener('input', generate);
  generate();

  copyBtn.addEventListener('click', () => {
    if (window.NikTool && typeof window.NikTool.copy === 'function') {
      window.NikTool.copy(outEl.value, copyBtn);
    } else if (navigator.clipboard) {
      navigator.clipboard.writeText(outEl.value);
    }
    msgEl.textContent = 'Lorem Ipsum copied to clipboard.';
  });

  clearBtn.addEventListener('click', () => {
    outEl.value = '';
    msgEl.textContent = 'Ready. Enter parameters above.';
  });
})();

