    const spec = spEl.value, EkGev = parseFloat(ekEl.value), B = parseFloat(bEl.value);
    if (isNaN(EkGev) || isNaN(B) || EkGev <= 0 || B <= 0) return;

    let m0Gev = 0.938272;
    let zCharge = 1;
    if (spec === 'electron') { m0Gev = 0.000511; zCharge = 1; }
    else if (spec === 'carbon') { m0Gev = 12 * 0.9315; zCharge = 6; }

