    brResEl.textContent = Math.round(Brho).toLocaleString() + ' T·m (Rigidity)';
    rhResEl.textContent = 'ρ = ' + Math.round(rhoM).toLocaleString() + ' meters Radius (Total Momentum p = ' + Math.round(pGev_c).toLocaleString() + ' GeV/c)';
  }

