mass-spring-simple-harmonic-motion-perio.js:
(() => {
  'use strict';
  const mEl = document.getElementById('sh-m'), kEl = document.getElementById('sh-k'), ampEl = document.getElementById('sh-amp');
  const tResEl = document.getElementById('sh-res-t'), enResEl = document.getElementById('sh-res-en');

  function update() {
    const m = parseFloat(mEl.value), k = parseFloat(kEl.value), x_cm = parseFloat(ampEl.value);
    if (isNaN(m) || isNaN(k) || isNaN(x_cm) || m <= 0 || k <= 0 || x_cm < 0) return;

    const x_m = x_cm / 100.0;

    // Angular frequency omega = sqrt( k / m )  [rad / s]
    const omega = Math.sqrt(k / m);

    // Period T = 2 * pi / omega = 2 * pi * sqrt( m / k )  [seconds]
    const T = (2.0 * Math.PI) / omega;
    const freq = 1.0 / T;

    // Max potential energy U_max = 0.5 * k * x^2  [Joules]
    const U_max = 0.5 * k * Math.pow(x_m, 2);

    // Max speed v_max = omega * x  [m / s]
    const v_max = omega * x_m;

    tResEl.textContent = 'Period T = ' + T.toFixed(3) + ' s (f = ' + freq.toFixed(2) + ' Hz)';
    enResEl.textContent = 'Angular ω = ' + omega.toFixed(2) + ' rad/s | Energy U = ' + U_max.toFixed(2) + ' J | Max Velocity v_max = ' + v_max.toFixed(2) + ' m/s @ k = ' + k + ' N/m';
  }

  [mEl, kEl, ampEl].forEach(el => el.addEventListener('input', update));
  update();
})();

matrix-determinant-calculator.js:
(() => {
  'use strict';
  const inputs = [
    ['m00','m01','m02'],
    ['m10','m11','m12'],
    ['m20','m21','m22']
  ].map(row => row.map(id => document.getElementById(id)));

  const btn = document.getElementById('primary-action-btn'), clearBtn = document.getElementById('clear-action-btn');
  const msgEl = document.getElementById('tool-message'), resCard = document.getElementById('mat-res-card');
  const resDet = document.getElementById('mat-res-det'), resStatus = document.getElementById('mat-res-status');

  function setMsg(t, e) { msgEl.textContent = t; msgEl.className = 'message' + (e ? ' error' : ' success'); }

  btn.addEventListener('click', () => {
    const vals = inputs.map(row => row.map(el => parseFloat(el.value)));
    if (vals.flat().some(isNaN)) {
      setMsg('Please fill in all 9 matrix cells with valid numbers.', true);
      resCard.style.display = 'none'; return;
    }

    const [[a, b, c], [d, e, f], [g, h, i]] = vals;
    // det = a(ei − fh) − b(di − fg) + c(dh − eg)
    const det = a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g);

    resDet.textContent = det.toFixed(4);
    if (Math.abs(det) < 1e-12) {
      resStatus.textContent = 'Singular (Non-Invertible)';
      resStatus.style.color = '#c53030';
    } else {
      resStatus.textContent = 'Invertible (det ≠ 0)';
      resStatus.style.color = '#22543d';
    }

    resCard.style.display = 'block';
    setMsg('Matrix determinant calculated.');
  });

  clearBtn.addEventListener('click', () => {
    inputs.flat().forEach(el => el.value = '');
    resCard.style.display = 'none';
    msgEl.textContent = 'Ready. Enter parameters above.';
    msgEl.className = 'message';
  });
})();

matrix-eigenvalue-2x2-calculator.js:
(() => {
  'use strict';
  const aEl = document.getElementById('eig-a'), bEl = document.getElementById('eig-b');
  const cEl = document.getElementById('eig-c'), dEl = document.getElementById('eig-d');
  const l1El = document.getElementById('eig-res-l1'), l2El = document.getElementById('eig-res-l2'), trEl = document.getElementById('eig-res-trace');

  function update() {
    const a = parseFloat(aEl.value), b = parseFloat(bEl.value);
    const c = parseFloat(cEl.value), d = parseFloat(dEl.value);
    if (isNaN(a) || isNaN(b) || isNaN(c) || isNaN(d)) return;

    // Trace T = a + d
    const T = a + d;
    // Determinant D = ad - bc
    const D = (a * d) - (b * c);
    // Discriminant Delta = T^2 - 4D
    const delta = Math.pow(T, 2) - (4 * D);

    trEl.textContent = 'Tr(A) = ' + T.toFixed(2) + ', Det(A) = ' + D.toFixed(2);

    if (delta >= 0) {
      const l1 = (T + Math.sqrt(delta)) / 2;
      const l2 = (T - Math.sqrt(delta)) / 2;
      l1El.textContent = 'λ₁ = ' + l1.toFixed(2);
      l2El.textContent = 'λ₂ = ' + l2.toFixed(2);
    } else {
      const real = (T / 2).toFixed(2);
      const imag = (Math.sqrt(-delta) / 2).toFixed(2);
      l1El.textContent = 'λ₁ = ' + real + ' + ' + imag + 'i';
      l2El.textContent = 'λ₂ = ' + real + ' - ' + imag + 'i';
    }
  }

  [aEl, bEl, cEl, dEl].forEach(el => el.addEventListener('input', update));
  update();
})();

matrix-eigenvalues-eigenvectors-characte.js:
(() => {
  'use strict';
  const aEl = document.getElementById('eig-a'), bEl = document.getElementById('eig-b');
  const cEl = document.getElementById('eig-c'), dEl = document.getElementById('eig-d');
  const vResEl = document.getElementById('eig-res-val'), vcResEl = document.getElementById('eig-res-vec');

  function update() {
    const a = parseFloat(aEl.value), b = parseFloat(bEl.value);
    const c = parseFloat(cEl.value), d = parseFloat(dEl.value);

    if (isNaN(a) || isNaN(b) || isNaN(c) || isNaN(d)) return;

    // Trace T = a + d
    const T = a + d;
    // Determinant D = a*d - b*c
    const D = (a * d) - (b * c);

    // Characteristic polynomial: lambda^2 - T*lambda + D = 0
    // Discriminant delta = T^2 - 4*D
    const delta = Math.pow(T, 2) - (4.0 * D);

    let l1_str = '', l2_str = '', vec_str = '';
    let color = '#22543d';

    if (delta >= 0) {
      const l1 = (T + Math.sqrt(delta)) / 2.0;
      const l2 = (T - Math.sqrt(delta)) / 2.0;
      l1_str = l1.toFixed(2);
      l2_str = l2.toFixed(2);

      // Eigenvectors: (a - lambda)*x + b*y = 0 => [b, lambda - a]
      const v1 = b !== 0 ? '[' + b.toFixed(2) + ', ' + (l1 - a).toFixed(2) + ']ᵀ' : '[1, 0]ᵀ';
      const v2 = b !== 0 ? '[' + b.toFixed(2) + ', ' + (l2 - a).toFixed(2) + ']ᵀ' : '[0, 1]ᵀ';
      vec_str = 'Trace = ' + T.toFixed(2) + ' | Det = ' + D.toFixed(2) + ' | v₁ ≈ ' + v1 + ', v₂ ≈ ' + v2;
    } else {
      const realPart = T / 2.0;
      const imagPart = Math.sqrt(-delta) / 2.0;
      l1_str = realPart.toFixed(2) + ' + ' + imagPart.toFixed(2) + 'j';
      l2_str = realPart.toFixed(2) + ' - ' + imagPart.toFixed(2) + 'j';
      vec_str = 'Complex Conjugate Eigenvalues | Characteristic Eq: λ² - ' + T.toFixed(2) + 'λ + ' + D.toFixed(2) + ' = 0';
      color = '#2563eb';
    }

    vResEl.textContent = 'λ₁ = ' + l1_str + ', λ₂ = ' + l2_str;
    vResEl.style.color = color;
    vcResEl.textContent = vec_str;
    vcResEl.style.color = color;
  }

  [aEl, bEl, cEl, dEl].forEach(el => el.addEventListener('input', update));
  update();
})();

