mba-weighted-average-cost-of-capital-wac.js:
(() => {
  'use strict';
  const eqEl = document.getElementById('wc-eq'), dbtEl = document.getElementById('wc-dbt');
  const bEl = document.getElementById('wc-beta'), rfEl = document.getElementById('wc-rf');
  const rdEl = document.getElementById('wc-rd'), txEl = document.getElementById('wc-tax');
  const wacResEl = document.getElementById('wc-res-wacc'), capResEl = document.getElementById('wc-res-capm');

  const equityRiskPremium = 5.0; // Standard 5.0% historical market risk premium (r_m - r_f)

  function update() {
    const E = parseFloat(eqEl.value), D = parseFloat(dbtEl.value);
    const beta = parseFloat(bEl.value), rf_pct = parseFloat(rfEl.value);
    const rd_pct = parseFloat(rdEl.value), tax_pct = parseFloat(txEl.value);

    if (isNaN(E) || isNaN(D) || isNaN(beta) || isNaN(rf_pct) || isNaN(rd_pct) || isNaN(tax_pct) || E <= 0 || D < 0) return;

    const V = E + D;
    const w_e = E / V;
    const w_d = D / V;

    // CAPM Cost of Equity: r_e = r_f + beta * ERP
    const r_e_pct = rf_pct + (beta * equityRiskPremium);

    // After-tax cost of debt: r_d_after_tax = r_d * ( 1 - T_c )
    const tax_rate = tax_pct / 100.0;
    const r_d_after_tax_pct = rd_pct * (1.0 - tax_rate);

    // WACC = (w_e * r_e) + (w_d * r_d_after_tax)
    const WACC = (w_e * r_e_pct) + (w_d * r_d_after_tax_pct);

    wacResEl.textContent = 'WACC = ' + WACC.toFixed(2) + '% Discount Rate';
    capResEl.textContent = 'Cost of Equity r_e = ' + r_e_pct.toFixed(2) + '% | After-Tax Debt = ' + r_d_after_tax_pct.toFixed(2) + '% (Equity: ' + (w_e*100).toFixed(0) + '%, Debt: ' + (w_d*100).toFixed(0) + '%)';
  }

  [eqEl, dbtEl, bEl, rfEl, rdEl, txEl].forEach(el => el.addEventListener('input', update));
  update();
})();

mccabe-thiele-fractional-distillation-st.js:
(() => {
  'use strict';
  const xdEl = document.getElementById('mt-xd'), xbEl = document.getElementById('mt-xb');
  const zfEl = document.getElementById('mt-zf'), rEl = document.getElementById('mt-r');
  const stResEl = document.getElementById('mt-res-stages'), rmResEl = document.getElementById('mt-res-rmin');

  function update() {
    const xD = parseFloat(xdEl.value), xB = parseFloat(xbEl.value);
    const zF = parseFloat(zfEl.value), R = parseFloat(rEl.value);

    if (isNaN(xD) || isNaN(xB) || isNaN(zF) || isNaN(R) || xD <= zF || zF <= xB || R <= 0) return;

    // Relative volatility alpha approx 2.5 (standard ethanol-water / benzene-toluene):
    const alpha = 2.5;

    // Minimum reflux ratio for saturated liquid feed (q=1):
    // y_pinch = alpha * zF / (1 + (alpha - 1)*zF)
    const y_pinch = (alpha * zF) / (1.0 + (alpha - 1.0) * zF);
    const R_min = (xD - y_pinch) / (y_pinch - zF);

    // Fenske minimum stages at total reflux: N_min = ln( (xD/(1-xD)) * ((1-xB)/xB) ) / ln(alpha)
    const N_min = Math.log( (xD / (1.0 - xD)) * ((1.0 - xB) / xB) ) / Math.log(alpha);

    // Gilliland correlation for theoretical stages N at actual reflux R:
    const X_gil = (R - R_min) / (R + 1.0);
    const Y_gil = X_gil > 0 ? 1.0 - Math.exp((1.0 + 54.4 * X_gil) / (11.0 + 117.2 * X_gil) * (X_gil - 1.0) / Math.sqrt(X_gil)) : 1.0;
    const N_stages = (N_min + Y_gil) / (1.0 - Y_gil);

    stResEl.textContent = 'Theoretical Stages N ≈ ' + (R > R_min ? N_stages.toFixed(1) : '∞ (R ≤ R_min)') + ' Stages';
    rmResEl.textContent = 'R_min = ' + R_min.toFixed(2) + ' | Operating R/R_min = ' + (R / R_min).toFixed(2) + '× (N_min = ' + N_min.toFixed(1) + ' trays @ total reflux)';
  }

  [xdEl, xbEl, zfEl, rEl].forEach(el => el.addEventListener('input', update));
  update();
})();

mccabe-thiele-reflux-ratio-feed-q-line-c.js:
(() => {
  'use strict';
  const rEl = document.getElementById('mct-r'), xdEl = document.getElementById('mct-xd');
  const xfEl = document.getElementById('mct-xf'), qEl = document.getElementById('mct-q');
  const rolResEl = document.getElementById('mct-res-rol'), qlResEl = document.getElementById('mct-res-qline');

  function update() {
    const R = parseFloat(rEl.value), xD = parseFloat(xdEl.value);
    const xF = parseFloat(xfEl.value), q = parseFloat(qEl.value);

    if (isNaN(R) || isNaN(xD) || isNaN(xF) || isNaN(q) || R <= 0 || xD <= 0 || xF <= 0) return;

    // Rectifying Operating Line (ROL): y = (R / (R + 1)) * x + (xD / (R + 1))
    const slopeROL = R / (R + 1.0);
    const interceptROL = xD / (R + 1.0);

    // Feed q-line: y = (q / (q - 1)) * x - (xF / (q - 1))
    let qlineStr = '';
    if (Math.abs(q - 1.0) < 1e-4) {
      qlineStr = 'Vertical line x = ' + xF.toFixed(3) + ' (Saturated Liquid Feed)';
    } else if (Math.abs(q) < 1e-4) {
      qlineStr = 'Horizontal line y = ' + xF.toFixed(3) + ' (Saturated Vapor Feed)';
    } else {
      const slopeQ = q / (q - 1.0);
      const interceptQ = -xF / (q - 1.0);
      qlineStr = 'y = ' + slopeQ.toFixed(3) + '·x + ' + interceptQ.toFixed(3) + ' (Slope = ' + slopeQ.toFixed(2) + ')';
    }

    rolResEl.textContent = 'ROL: y = ' + slopeROL.toFixed(3) + '·x + ' + interceptROL.toFixed(3);
    qlResEl.textContent = 'Feed q-Line: ' + qlineStr + ' | y-Intercept = ' + interceptROL.toFixed(3);
  }

  [rEl, xdEl, xfEl].forEach(el => el.addEventListener('input', update));
  qEl.addEventListener('change', update);
  update();
})();

