  function update() {
    const sbp = parseFloat(sEl.value), dbp = parseFloat(dEl.value);
    if (isNaN(sbp) || isNaN(dbp) || sbp <= dbp || dbp <= 0) return;

    // Pulse Pressure PP = SBP - DBP
