    invResEl.textContent = 'Inventory: ' + Math.round(totalMassKg).toLocaleString() + ' kg MLSS | Waste: ' + Math.round(dailyWastedKg).toLocaleString() + ' kg/d @ ' + targetMCRT + '-Day MCRT (θ_c)';
