membrane-osmotic-pressure-van-t-hoff-rev.js:
(() => {
  'use strict';
  const tdsEl = document.getElementById('ro-tds'), dpEl = document.getElementById('ro-dp');
  const aEl = document.getElementById('ro-a'), tEl = document.getElementById('ro-temp');
  const fxResEl = document.getElementById('ro-res-flux'), piResEl = document.getElementById('ro-res-pi');

  const R = 0.08314462618; // L * bar / (mol * K)
  const MW_NaCl = 58.44; // g / mol

  function update() {
    const TDS_mg_L = parseFloat(tdsEl.value), dP_bar = parseFloat(dpEl.value);
    const A_permeability = parseFloat(aEl.value), T_C = parseFloat(tEl.value);

    if (isNaN(TDS_mg_L) || isNaN(dP_bar) || isNaN(A_permeability) || isNaN(T_C) || TDS_mg_L <= 0 || dP_bar <= 0 || A_permeability <= 0 || T_C < -273.15) return;

    const T_K = T_C + 273.15;

    // Molarity M = (TDS_mg_L * 1e-3 g/L) / MW_NaCl  [mol / L]
    const M = (TDS_mg_L * 1e-3) / MW_NaCl;

    // Van 't Hoff osmotic pressure: Pi = i * M * R * T  (i = 2 for NaCl: Na+ and Cl-)  [bar]
    const i = 2.0;
    const Pi_bar = i * M * R * T_K;

    // Net driving pressure NDP = dP - Pi  [bar]
    const NDP_bar = dP_bar - Pi_bar;

    let flux_LMH = 0;
    if (NDP_bar > 0) {
      flux_LMH = A_permeability * NDP_bar;
    }

    fxResEl.textContent = 'Water Flux J_w = ' + (NDP_bar > 0 ? flux_LMH.toFixed(1) + ' LMH' : '0.0 LMH (ΔP < Π: Osmotic Backflow)');
    piResEl.textContent = 'Osmotic Π = ' + Pi_bar.toFixed(1) + ' bar | Net Driving Pressure NDP = ' + NDP_bar.toFixed(1) + ' bar (' + (TDS_mg_L/1000).toFixed(1) + ' g/L @ ' + T_C + '°C)';
  }

  [tdsEl, dpEl, aEl, tEl].forEach(el => el.addEventListener('input', update));
  update();
})();

mesh-knudsen-number-continuum-navier-sto.js:
(() => {
  'use strict';
  const pEl = document.getElementById('kn-p'), tEl = document.getElementById('kn-t');
  const lEl = document.getElementById('kn-l'), dEl = document.getElementById('kn-d');
  const knResEl = document.getElementById('kn-res-kn'), rgResEl = document.getElementById('kn-res-reg');

  const kB = 1.380649e-23; // J / K (Boltzmann constant)

  function update() {
    const P = parseFloat(pEl.value), Tc = parseFloat(tEl.value);
    const LMm = parseFloat(lEl.value), dNm = parseFloat(dEl.value);

    if (isNaN(P) || isNaN(Tc) || isNaN(LMm) || isNaN(dNm) || P <= 0 || LMm <= 0 || dNm <= 0 || Tc < -273.15) return;

    const Tk = Tc + 273.15;
    const dM = dNm * 1e-9;
    const LM = LMm * 1e-3;

    // Molecular mean free path lambda = ( kB * T ) / ( sqrt(2) * pi * d^2 * P )  [meters]
    const lambdaM = (kB * Tk) / (Math.SQRT2 * Math.PI * Math.pow(dM, 2) * P);
    const lambdaNm = lambdaM * 1e9;
    const lambdaUm = lambdaM * 1e6;

    // Knudsen number Kn = lambda / L
    const Kn = lambdaM / LM;

    let regime = '';
    let color = '#22543d';

    if (Kn < 0.001) {
      regime = 'CONTINUUM FLOW (Kn < 0.001): Standard Navier-Stokes Equations with No-Slip Wall Boundary';
      color = '#22543d';
    } else if (Kn < 0.1) {
      regime = 'SLIP FLOW (0.001 < Kn < 0.1): Navier-Stokes with Maxwell Velocity Slip & Temperature Jump';
      color = '#2563eb';
    } else if (Kn < 10.0) {
      regime = 'TRANSITION REGIME (0.1 < Kn < 10): DSMC (Direct Simulation Monte Carlo) Particle Methods Required';
      color = '#d97706';
    } else {
      regime = 'FREE MOLECULAR FLOW (Kn > 10): Intermolecular Collisions Negligible - Collisionless Gas Kinetics';
      color = '#c53030';
    }

    knResEl.textContent = 'Kn = ' + (Kn < 0.01 ? Kn.toExponential(3) : Kn.toFixed(4)) + ' (Mean Free Path λ = ' + (lambdaUm < 1.0 ? lambdaNm.toFixed(1) + ' nm' : lambdaUm.toFixed(2) + ' μm)');
    rgResEl.textContent = regime;
    rgResEl.style.color = color;
  }

  [pEl, tEl, lEl].forEach(el => el.addEventListener('input', update));
  dEl.addEventListener('change', update);
  update();
})();

