    } else if (mode === 'noncomp') {
      Km_app = Km;
      Vmax_app = Vmax / alpha;
      desc = 'NON-COMPETITIVE: Allosteric binding (Vmax reduced by ' + alpha.toFixed(1) + '×, Km unchanged)';
    } else {
      Km_app = Km / alpha;
      Vmax_app = Vmax / alpha;
      desc = 'UNCOMPETITIVE: Binds ES complex only (Both Km and Vmax reduced by ' + alpha.toFixed(1) + '×)';
