  const aEl = document.getElementById('mod-a'), mEl = document.getElementById('mod-m');
  const xEl = document.getElementById('mod-res-x'), chkEl = document.getElementById('mod-res-check');

  function extGCD(a, b) {
    if (b === 0) return { gcd: a, x: 1, y: 0 };
    const { gcd, x: x1, y: y1 } = extGCD(b, a % b);
    const x = y1;
    const y = x1 - Math.floor(a / b) * y1;
    return { gcd, x, y };
  }

  function update() {
    const a = parseInt(aEl.value, 10);
    const m = parseInt(mEl.value, 10);
    if (isNaN(a) || isNaN(m) || m <= 1) return;

    const { gcd, x } = extGCD(a, m);
    if (gcd !== 1) {
      xEl.textContent = 'No Inverse Exists';
      xEl.style.color = '#c53030';
      chkEl.textContent = 'GCD(' + a + ', ' + m + ') = ' + gcd + ' ≠ 1 (Not Coprime)';
      return;
    }

    const inv = ((x % m) + m) % m;
    xEl.textContent = 'x = ' + inv;
    xEl.style.color = '#22543d';
    chkEl.textContent = '(' + a + ' × ' + inv + ') mod ' + m + ' = ' + ((a * inv) % m);
  }

  aEl.addEventListener('input', update);
  mEl.addEventListener('input', update);
  update();
})();

moho-crustal-depth-airy-isostasy-calcula.js:
(() => {
  'use strict';
  const hEl = document.getElementById('iso-h'), t0El = document.getElementById('iso-t0');
  const rcEl = document.getElementById('iso-rhoc'), rmEl = document.getElementById('iso-rhom');
  const mResEl = document.getElementById('iso-res-moho'), rResEl = document.getElementById('iso-res-root');

  function update() {
    const h = parseFloat(hEl.value), T0 = parseFloat(t0El.value);
    const rho_c = parseFloat(rcEl.value), rho_m = parseFloat(rmEl.value);

    if (isNaN(h) || isNaN(T0) || isNaN(rho_c) || isNaN(rho_m) || h <= 0 || T0 <= 0 || rho_c <= 0 || rho_m <= rho_c) return;

    // Airy Isostasy root depth b = h * rho_c / (rho_m - rho_c)
    const deltaRho = rho_m - rho_c;
    const bRoot = h * (rho_c / deltaRho);

    // Total crustal thickness = T0 + h + b
    const totalCrust = T0 + h + bRoot;
    // Moho depth below sea level = T0 + b
    const mohoDepth = T0 + bRoot;

    mResEl.textContent = mohoDepth.toFixed(1) + ' km Moho Depth Below Sea Level';
    rResEl.textContent = 'Sub-Crustal Root: ' + bRoot.toFixed(1) + ' km (Total Crust: ' + totalCrust.toFixed(1) + ' km, Root/Top Ratio: ' + (bRoot/h).toFixed(1) + ':1)';
  }

  [hEl, t0El, rcEl, rmEl].forEach(el => el.addEventListener('input', update));
  update();
})();

mohr-circle-2d-principal-stresses-maximu.js:
(() => {
  'use strict';
  const sxEl = document.getElementById('mc-sx'), syEl = document.getElementById('mc-sy'), txyEl = document.getElementById('mc-txy');
  const p1ResEl = document.getElementById('mc-res-p1'), tauResEl = document.getElementById('mc-res-tau');

  function update() {
    const sx = parseFloat(sxEl.value), sy = parseFloat(syEl.value), txy = parseFloat(txyEl.value);
    if (isNaN(sx) || isNaN(sy) || isNaN(txy)) return;

    // Center of Mohr's circle: sigma_avg = (sx + sy) / 2
    const s_avg = (sx + sy) / 2.0;

    // Radius R = sqrt( ((sx - sy)/2)^2 + txy^2 ) = tau_max
    const R = Math.sqrt(Math.pow((sx - sy) / 2.0, 2) + Math.pow(txy, 2));

    // Principal stresses: sigma_1 = s_avg + R, sigma_2 = s_avg - R
    const s1 = s_avg + R;
    const s2 = s_avg - R;

    // Principal angle: tan(2 * theta_p) = (2 * txy) / (sx - sy)
    const theta_p_rad = 0.5 * Math.atan2(2.0 * txy, sx - sy);
    const theta_p_deg = (theta_p_rad * 180.0) / Math.PI;

    p1ResEl.textContent = 'σ₁ = ' + (s1 >= 0 ? '+' : '') + s1.toFixed(2) + ' MPa, σ₂ = ' + (s2 >= 0 ? '+' : '') + s2.toFixed(2) + ' MPa';
    tauResEl.textContent = 'Max Shear τ_max = ' + R.toFixed(2) + ' MPa | Principal Angle θ_p = ' + theta_p_deg.toFixed(2) + '° (Circle Center σ_avg = ' + s_avg.toFixed(1) + ' MPa)';
  }

  [sxEl, syEl, txyEl].forEach(el => el.addEventListener('input', update));
  update();
})();

