    p12ResEl.textContent = 'σ₁ = ' + (sigma_1 >= 0 ? '+' : '') + sigma_1.toFixed(1) + ' MPa | σ₂ = ' + (sigma_2 >= 0 ? '+' : '') + sigma_2.toFixed(1) + ' MPa';
    tuResEl.textContent = 'Max Shear τ_max = ' + tau_max.toFixed(1) + ' MPa (Radius R) | θ_p = ' + theta_p_deg.toFixed(1) + '° (Center σ_avg = ' + sigma_avg.toFixed(1) + ' MPa)';
  }

  [sxEl, syEl, txyEl].forEach(el => el.addEventListener('input', update));
  update();
})();

mohr-coulomb-shear-strength-envelope-cal.js:
(() => {
  'use strict';
  const sEl = document.getElementById('mc-sig'), cEl = document.getElementById('mc-c'), pEl = document.getElementById('mc-phi');
  const tResEl = document.getElementById('mc-res-tau'), fResEl = document.getElementById('mc-res-fail');

  function update() {
    const sigma = parseFloat(sEl.value), c = parseFloat(cEl.value), phiDeg = parseFloat(pEl.value);
    if (isNaN(sigma) || isNaN(c) || isNaN(phiDeg) || sigma < 0 || c < 0 || phiDeg < 0 || phiDeg > 45) return;

    const phiRad = (phiDeg * Math.PI) / 180;
    const tau = c + (sigma * Math.tan(phiRad));
    const thetaF = 45 + (phiDeg / 2);
    const tauFric = sigma * Math.tan(phiRad);

    tResEl.textContent = tau.toFixed(1) + ' kPa (Shear Strength τ_f)';
    fResEl.textContent = 'Rupture Plane θ_f = ' + thetaF.toFixed(1) + '° (Cohesive: ' + c.toFixed(1) + ' kPa, Frictional: ' + tauFric.toFixed(1) + ' kPa)';
  }

  [sEl, cEl, pEl].forEach(el => el.addEventListener('input', update));
  update();
})();

mohr-coulomb-shear-strength-soil-cohesio.js:
(() => {
  'use strict';
  const cEl = document.getElementById('mc-c'), phiEl = document.getElementById('mc-phi');
  const sgEl = document.getElementById('mc-sigma'), uEl = document.getElementById('mc-u');
  const tfResEl = document.getElementById('mc-res-tauf'), efResEl = document.getElementById('mc-res-eff');

  function update() {
    const c = parseFloat(cEl.value), phi_deg = parseFloat(phiEl.value);
    const sigma = parseFloat(sgEl.value), u = parseFloat(uEl.value);

    if (isNaN(c) || isNaN(phi_deg) || isNaN(sigma) || isNaN(u) || c < 0 || phi_deg < 0 || phi_deg >= 60 || sigma < 0) return;

    // Effective stress: sigma_prime = sigma - u
    const sigma_prime = Math.max(0.0, sigma - u);
    const phi_rad = (phi_deg * Math.PI) / 180.0;

    // Frictional strength component: sigma_prime * tan(phi)
    const tau_frictional = sigma_prime * Math.tan(phi_rad);

    // Total Mohr-Coulomb shear strength: tau_f = c + sigma_prime * tan(phi)
    const tau_f = c + tau_frictional;

    const pct_friction = tau_f > 0 ? (tau_frictional / tau_f) * 100.0 : 0;

    tfResEl.textContent = 'Shear Strength τ_f = ' + tau_f.toFixed(1) + ' kPa';
    efResEl.textContent = 'Effective σ' = ' + sigma_prime.toFixed(1) + ' kPa (σ-u) | Friction = ' + tau_frictional.toFixed(1) + ' kPa (' + pct_friction.toFixed(1) + '%) + Cohesion ' + c + ' kPa';
  }

  [cEl, phiEl, sgEl, uEl].forEach(el => el.addEventListener('input', update));
  update();
})();

