      out += 'n = ' + a + ' moles, V = ' + b + ' L\n';
      out += 'Molarity = ' + M.toFixed(4) + ' M (mol/L)';
    } else if (mode === 'n') {
      var n = a * b;
      out += 'M = ' + a + ' mol/L, V = ' + b + ' L\n';
      out += 'Moles = ' + n.toFixed(4) + ' moles';
