    const nCollisions = Math.ceil(u / xi);

    nResEl.textContent = nCollisions + ' Collisions to Thermal Energy';
    xiResEl.textContent = 'ξ = ' + xi.toFixed(3) + ' (Total Lethargy u = ' + u.toFixed(2) + ')';
