oblique-shock-wave-theta-beta-mach-calcu.js:
(() => {
  'use strict';
  const m1El = document.getElementById('obs-m1'), bEl = document.getElementById('obs-beta');
  const thResEl = document.getElementById('obs-res-theta'), m2ResEl = document.getElementById('obs-res-m2');

  const gamma = 1.40;

  function update() {
    const M1 = parseFloat(m1El.value), beta_deg = parseFloat(bEl.value);
    if (isNaN(M1) || isNaN(beta_deg) || M1 <= 1.0 || beta_deg <= 0 || beta_deg >= 90) return;

    const beta_rad = (beta_deg * Math.PI) / 180.0;
    const sin_b = Math.sin(beta_rad);
    const cos_b = Math.cos(beta_rad);
    const cot_b = 1.0 / Math.tan(beta_rad);

    // Normal Mach number upstream: M_n1 = M1 * sin(beta)
    const M_n1 = M1 * sin_b;
    if (M_n1 <= 1.0) {
      thResEl.textContent = 'NO SHOCK (M_n1 = M₁·sin β ≤ 1.0)';
      m2ResEl.textContent = 'M₁·sin β must exceed 1.0 for an oblique shock';
      return;
    }

    // Theta-Beta-M relation:
    // tan(theta) = 2 * cot(beta) * [ (M1^2 * sin^2(beta) - 1) / ( M1^2 * (gamma + cos(2*beta)) + 2 ) ]
    const num = Math.pow(M1, 2) * Math.pow(sin_b, 2) - 1.0;
    const den = Math.pow(M1, 2) * (gamma + Math.cos(2.0 * beta_rad)) + 2.0;
    const tan_theta = 2.0 * cot_b * (num / den);

    const theta_rad = Math.atan(tan_theta);
    const theta_deg = (theta_rad * 180.0) / Math.PI;

    // Normal Mach downstream:
    const M_n2 = Math.sqrt((Math.pow(M_n1, 2) + 2.0 / (gamma - 1.0)) / ((2.0 * gamma / (gamma - 1.0)) * Math.pow(M_n1, 2) - 1.0));
    // Downstream total Mach M2 = M_n2 / sin(beta - theta)
    const M2 = M_n2 / Math.sin(beta_rad - theta_rad);

    // Static pressure ratio P2 / P1 = 1 + (2*gamma / (gamma+1)) * (M_n1^2 - 1)
    const p_ratio = 1.0 + ((2.0 * gamma) / (gamma + 1.0)) * (Math.pow(M_n1, 2) - 1.0);

    thResEl.textContent = 'Wedge Deflection θ = ' + theta_deg.toFixed(2) + '°';
    m2ResEl.textContent = 'Downstream Mach M₂ = ' + M2.toFixed(2) + ' | P₂/P₁ = ' + p_ratio.toFixed(2) + ' (M_n1 = ' + M_n1.toFixed(2) + ')';
  }

  [m1El, bEl].forEach(el => el.addEventListener('input', update));
  update();
})();

oblique-shock-wave-theta-beta-mach-relat.js:
(() => {
  'use strict';
  const m1El = document.getElementById('ob-m1'), thEl = document.getElementById('ob-theta'), gmEl = document.getElementById('ob-gamma');
  const btResEl = document.getElementById('ob-res-beta'), psResEl = document.getElementById('ob-res-post');

  function update() {
    const M1 = parseFloat(m1El.value), theta_deg = parseFloat(thEl.value), gamma = parseFloat(gmEl.value);
    if (isNaN(M1) || isNaN(theta_deg) || isNaN(gamma) || M1 <= 1 || theta_deg <= 0 || gamma <= 1) return;

    const theta_rad = (theta_deg * Math.PI) / 180.0;
    const mu_mach_rad = Math.asin(1.0 / M1);

    let beta_weak = 0, found = false;
    for (let b_deg = (mu_mach_rad * 180 / Math.PI) + 0.1; b_deg <= 89.9; b_deg += 0.05) {
      const b_rad = (b_deg * Math.PI) / 180.0;
      const num = 2.0 * (1.0 / Math.tan(b_rad)) * (Math.pow(M1, 2) * Math.pow(Math.sin(b_rad), 2) - 1.0);
      const den = Math.pow(M1, 2) * (gamma + Math.cos(2.0 * b_rad)) + 2.0;
      const tan_theta_calc = num / den;

      if (tan_theta_calc >= Math.tan(theta_rad)) {
        beta_weak = b_deg;
        found = true;
        break;
      }
    }

    if (!found) {
      btResEl.textContent = 'DETACHED BOW SHOCK (θ > θ_max)';
      btResEl.style.color = '#c53030';
      psResEl.textContent = 'Wedge angle ' + theta_deg + '° exceeds maximum attachment angle for M₁=' + M1 + ' (Strong curved detached shock forms)';
      return;
    }

    const beta_rad = (beta_weak * Math.PI) / 180.0;
    const M1n = M1 * Math.sin(beta_rad);
    const p2_p1 = 1.0 + ((2.0 * gamma / (gamma + 1.0)) * (Math.pow(M1n, 2) - 1.0));
    const M2n_sq = (Math.pow(M1n, 2) + (2.0 / (gamma - 1.0))) / (((2.0 * gamma / (gamma - 1.0)) * Math.pow(M1n, 2)) - 1.0);
    const M2 = Math.sqrt(M2n_sq) / Math.sin(beta_rad - theta_rad);

    btResEl.textContent = 'Shock Angle β = ' + beta_weak.toFixed(2) + '° (Weak Attached Shock)';
    btResEl.style.color = '#22543d';
    psResEl.textContent = 'Downstream M₂ = ' + M2.toFixed(2) + ' | Pressure Jump p₂/p₁ = ' + p2_p1.toFixed(2) + '× (M₁n = ' + M1n.toFixed(2) + ' @ θ=' + theta_deg + '°)';
  }

  [m1El, thEl, gmEl].forEach(el => el.addEventListener('input', update));
  update();
})();

