(function() {
  'use strict';
  var slug = 'optical-fiber-attenuation-power-budget-link-calculator';

  function el(id) {
    return document.getElementById(slug + '-' + id);
  }

  var outputEl = document.getElementById(slug + '-output');
  var msgEl = document.getElementById(slug + '-message');
  var btn = document.getElementById('primary-action-btn');
  var copyBtn = document.getElementById('copy-output');
  var clearBtn = document.getElementById('clear-text');

  function setMsg(t, err) {
    msgEl.textContent = t;
    msgEl.classList.toggle('is-error', !!err);
  }

  function calculate() {
    try {

      var L = parseFloat(el('len-km').value);
      var alpha = parseFloat(el('alpha-db-km').value);
      var conn = parseFloat(el('conn-loss-db').value);
      var ptx = parseFloat(el('ptx-dbm').value);
      var prx = parseFloat(el('prx-sens-dbm').value);
      if (isNaN(L) || L <= 0 || isNaN(alpha) || alpha < 0 || isNaN(conn) || isNaN(ptx) || isNaN(prx)) {
        return { err: 'Please enter valid numerical values for fiber link parameters.' };
      }
      var total_fiber_loss = L * alpha;
      var total_attenuation = total_fiber_loss + conn;
      var avail_budget = ptx - prx;
      var margin_db = avail_budget - total_attenuation;
      var max_dist_km = (avail_budget - conn) / alpha;
      var out = 'FIBER OPTIC LINK POWER BUDGET ANALYSIS\n';
      out += '======================================\n';
      out += 'Link Distance (L)     : ' + L + ' km\n';
      out += 'Fiber Attenuation (α) : ' + alpha + ' dB/km\n';
      out += 'Connectors/Splices    : ' + conn + ' dB\n';
      out += 'Transmitter Power     : ' + ptx + ' dBm\n';
      out += 'Receiver Sensitivity  : ' + prx + ' dBm\n\n';
      out += 'RESULTS:\n';
      out += 'Total Attenuation     : ' + total_attenuation.toFixed(2) + ' dB\n';
      out += 'Available Power Budget: ' + avail_budget.toFixed(2) + ' dB\n';
      out += 'Link Power Margin     : ' + margin_db.toFixed(2) + ' dB\n';
      out += 'Max Distance @ 3dB Margin: ' + ((avail_budget - conn - 3) / alpha).toFixed(2) + ' km\n';
      out += 'Link Status           : ' + (margin_db >= 3 ? 'PASS (Good Power Margin >= 3dB)' : (margin_db >= 0 ? 'WARNING (Low Margin < 3dB)' : 'FAIL (Insufficient Power)'));
      return { out: out, msg: 'Fiber optic link budget calculated successfully.' };

    } catch(e) {
      return { err: 'Error during calculation: ' + e.message };
    }
  }

  btn.addEventListener('click', function() {
    var res = calculate();
    if (res.err) {
      outputEl.value = '';
      copyBtn.disabled = true;
      setMsg(res.err, true);
    } else {
      outputEl.value = res.out;
      copyBtn.disabled = false;
      setMsg(res.msg || 'Calculation completed successfully.');
    }
  });

  copyBtn.addEventListener('click', function() {
    if (window.NikTool && typeof window.NikTool.copy === 'function') {
      window.NikTool.copy(outputEl.value, copyBtn);
    } else if (navigator.clipboard) {
      navigator.clipboard.writeText(outputEl.value);
    }
    setMsg('Result copied to clipboard.');
  });

  clearBtn.addEventListener('click', function() {
    var inputs = ['len-km', 'alpha-db-km', 'conn-loss-db', 'ptx-dbm', 'prx-sens-dbm'];
    inputs.forEach(function(id) {
      var elem = el(id);
      if (elem) elem.value = elem.defaultValue || '';
    });
    outputEl.value = '';
    copyBtn.disabled = true;
    setMsg('Cleared. Enter values above.');
  });
})();

optical-fiber-numerical-aperture-accepta.js:
(() => {
  'use strict';
  const ncEl = document.getElementById('of-ncore'), ncdEl = document.getElementById('of-nclad');
  const aEl = document.getElementById('of-a'), lmEl = document.getElementById('of-lambda');
  const naResEl = document.getElementById('of-res-na'), vnResEl = document.getElementById('of-res-vnum');

  function update() {
    const n_core = parseFloat(ncEl.value), n_clad = parseFloat(ncdEl.value);
    const a_um = parseFloat(aEl.value), lambda_nm = parseFloat(lmEl.value);

    if (isNaN(n_core) || isNaN(n_clad) || isNaN(a_um) || isNaN(lambda_nm) || n_core <= n_clad || n_clad <= 0 || a_um <= 0 || lambda_nm <= 0) return;

    // Numerical Aperture: NA = sqrt( n_core^2 - n_clad^2 )
    const NA = Math.sqrt(Math.pow(n_core, 2) - Math.pow(n_clad, 2));

    // Acceptance angle in air (n0 = 1): theta_acc = asin(NA)  [rad -> deg]
    const theta_acc_rad = Math.asin(Math.min(1.0, NA));
    const theta_acc_deg = (theta_acc_rad * 180.0) / Math.PI;

    // Normalized frequency V-number: V = ( 2 * pi * a / lambda ) * NA
    const a_nm = a_um * 1000.0;
    const V = (2.0 * Math.PI * a_nm / lambda_nm) * NA;

    // Approximate number of guided spatial modes: M approx V^2 / 2 for multi-mode
    const is_smf = V < 2.4048;
    const num_modes = is_smf ? 1 : Math.round(Math.pow(V, 2) / 2.0);

    let status = '', color = '#22543d';
    if (is_smf) {
      status = 'SINGLE-MODE FIBER (V = ' + V.toFixed(3) + ' < 2.405: Zero intermodal dispersion ✓)';
      color = '#22543d';
    } else {
      status = 'MULTI-MODE FIBER (V = ' + V.toFixed(2) + ' ≥ 2.405: Guided modes M ≈ ' + num_modes + ')';
      color = '#ea580c';
    }

    naResEl.textContent = 'Numerical Aperture NA = ' + NA.toFixed(4) + ' (Acceptance θ = ' + theta_acc_deg.toFixed(2) + '°)';
    vnResEl.textContent = 'V-Number = ' + V.toFixed(3) + ' (' + status + ')';
    vnResEl.style.color = color;
  }

  [ncEl, ncdEl, aEl, lmEl].forEach(el => el.addEventListener('input', update));
  update();
})();

