(() => {
  'use strict';
  const thEl = document.getElementById('pl-th'), phiEl = document.getElementById('pl-phi');
  const eResEl = document.getElementById('pl-res-exp'), pResEl = document.getElementById('pl-res-pur');

  function update() {
    const thDeg = parseFloat(thEl.value), phiDeg = parseFloat(phiEl.value);
    if (isNaN(thDeg) || isNaN(phiDeg)) return;

    const thRad = (thDeg * Math.PI) / 180;
    const phiRad = (phiDeg * Math.PI) / 180;

    const sx = Math.sin(thRad) * Math.cos(phiRad);
    const sy = Math.sin(thRad) * Math.sin(phiRad);
    const sz = Math.cos(thRad);
    const norm = Math.sqrt(sx*sx + sy*sy + sz*sz);

    eResEl.textContent = '⟨σ_x⟩ = ' + sx.toFixed(3) + ' | ⟨σ_y⟩ = ' + sy.toFixed(3) + ' | ⟨σ_z⟩ = ' + sz.toFixed(3);
    pResEl.textContent = 'Purity Tr(ρ²) = 1.000 (Pure State, |r| = ' + norm.toFixed(3) + ', Energy Eigenstate Z-Bias: ' + sz.toFixed(3) + ')';
  }

  thEl.addEventListener('input', update);
  phiEl.addEventListener('input', update);
  update();
})();

pcr-amplification-efficiency-cycle-numbe.js:
(() => {
  'use strict';
  const n0El = document.getElementById('pc-n0'), cEl = document.getElementById('pc-c'), efEl = document.getElementById('pc-eff');
  const ydResEl = document.getElementById('pc-res-yield'), fdResEl = document.getElementById('pc-res-fold');

  function update() {
    const N0 = parseFloat(n0El.value), C = parseFloat(cEl.value), eff_pct = parseFloat(efEl.value);
    if (isNaN(N0) || isNaN(C) || isNaN(eff_pct) || N0 <= 0 || C < 0 || eff_pct <= 0) return;

    const E = eff_pct / 100.0;

    // Exponential PCR formula: N = N0 * ( 1 + E )^C
    const multiplier = Math.pow(1.0 + E, C);
    const N_total = N0 * multiplier;

    // Mass in picomoles: moles = N_total / Avogadro (6.022e23) => pmol = moles * 1e12
    const pmol = (N_total / 6.02214076e23) * 1e12;

    ydResEl.textContent = 'Yield N = ' + N_total.toExponential(2) + ' Copies';
    fdResEl.textContent = 'Fold Amplification = ' + multiplier.toExponential(2) + '× (' + (pmol < 1 ? (pmol * 1000).toFixed(1) + ' fmol' : pmol.toFixed(2) + ' pmol') + ' product @ ' + C + ' cycles, E = ' + eff_pct + '%)';
  }

  [n0El, cEl, efEl].forEach(el => el.addEventListener('input', update));
  update();
})();

pcr-primer-melting-temperature-tm-wallac.js:
(() => {
  'use strict';
  const seqEl = document.getElementById('pcr-seq');
  const tmResEl = document.getElementById('pcr-res-tm'), taResEl = document.getElementById('pcr-res-ta');

  function update() {
    const rawSeq = (seqEl.value || '').toUpperCase().replace(/[^ATGC]/g, '');
    if (!rawSeq || rawSeq.length === 0) return;

    let countA = 0, countT = 0, countG = 0, countC = 0;
    for (let char of rawSeq) {
      if (char === 'A') countA++;
      else if (char === 'T') countT++;
      else if (char === 'G') countG++;
      else if (char === 'C') countC++;
    }

    const totalLen = rawSeq.length;
    const gcCount = countG + countC;
    const atCount = countA + countT;
    const gc_pct = (gcCount / totalLen) * 100.0;

    let Tm = 0;
    if (totalLen <= 14) {
      // Wallace Rule for short oligo <= 14 bp: Tm = 2*(A+T) + 4*(G+C)
      Tm = (2.0 * atCount) + (4.0 * gcCount);
    } else {
      // SantaLucia / Marmur-Doty empirical formula for longer primers:
      // Tm = 64.9 + 41 * (gcCount - 16.4) / totalLen
      Tm = 64.9 + (41.0 * (gcCount - 16.4) / totalLen);
    }

    // Optimal annealing temperature Ta approx = Tm - 5 deg C
    const Ta = Tm - 5.0;

    let status = '';
    let color = '#22543d';

    if (gc_pct >= 40.0 && gc_pct <= 60.0 && totalLen >= 18 && totalLen <= 24) {
      status = 'OPTIMAL PRIMER DESIGN (18-24 bp, 40-60% GC Content: Strong specific binding)';
      color = '#22543d';
    } else if (totalLen < 18) {
      status = 'SHORT PRIMER (< 18 bp: Risk of non-specific annealing in genome)';
      color = '#d97706';
    } else {
      status = 'ACCEPTABLE (Check for primer-dimers or secondary hairpin loops)';
      color = '#2563eb';
    }

    tmResEl.textContent = 'Tm = ' + Tm.toFixed(1) + ' °C';
    tmResEl.style.color = color;
    taResEl.textContent = 'Optimal Annealing Ta = ' + Ta.toFixed(1) + ' °C (Length: ' + totalLen + ' bp | GC: ' + gc_pct.toFixed(1) + '% | ' + status.split(' (')[0] + ')';
    taResEl.style.color = color;
  }

  seqEl.addEventListener('input', update);
  update();
})();
